window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-580bc757974fff31"]={"versions": [{"id": "FIG-580bc757974fff31", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Verbindungsaufbaus, der Datenübertragung und des Verbindungsabbaus im SAE J1939 Transport Layer (J1939Tp) der AUTOSAR Classic Platform unter Nutzung der verbindungsgesteuerten Übertragung (Connection Mode Data Transfer, CMDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationspartner, die als vertikale, gestrichelte Lebenslinien dargestellt sind: den sendenden Knoten (Sender, links) und den empfangenden Knoten (Receiver, rechts). Kommuniziert wird über standardisierte J1939-Transportprotokollnachrichten: Connection Management Nachrichten (TP.CM_RTS, TP.CM_CTS, TP.CM_EndOfMsgACK) sowie Datenübertragungsnachrichten (TP.DT). Relevante Zeitparameter sind T2 (Receiver-Wartezeit auf das nächste Datenpaket) und T3 (Sender-Wartezeit auf CTS).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Verbindungsaufbau: Der Sender initiiert die CMDT-Sitzung durch Senden von <code>TP.CM_RTS</code> mit den Parametern für 3 Pakete und eine Gesamtnutzdatenlänge von 16 Bytes an den Receiver. Der Sender startet dabei die Überwachung des T3-Timeouts.\n</li><li>Bestätigung / Flusssteuerung: Der Receiver antwortet mit <code>TP.CM_CTS with 2 Packets</code>, wodurch der Sender autorisiert wird, zunächst zwei Pakete zu übertragen. Der Receiver startet die T2-Timeout-Überwachung für die ausstehenden Datenpakete.\n</li><li>Paketübertragung (Block 1): Der Sender überträgt aufeinanderfolgend zwei Datenpakete (<code>TP.DT</code>).\n</li><li>Erneute Flusssteuerung: Nach Empfang des zweiten Datenpakets sendet der Receiver ein weiteres <code>TP.CM_CTS with 1 Packet</code>.\n</li><li>Paketübertragung (Block 2): Der Sender sendet das dritte und letzte Datenpaket (<code>TP.DT</code>).\n</li><li>Verbindungsabschluss: Nach erfolgreichem Empfang aller spezifizierten Pakete schließt der Receiver die Transaktion mit einer Endbestätigung (<code>TP.CM_EndOfMsgACK</code>) ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für einen fehlerfreien CMDT-Übertragungsablauf gemäß SAE J1939-21 bzw. AUTOSAR J1939Tp. Entwickler müssen sicherstellen, dass die softwareseitige Flusssteuerung die Anzahl der in CTS angeforderten Pakete strikt einhält, Timeouts für T2 und T3 konform überwacht werden und der Puffer nach Erhalt des EndOfMsgACK freigegeben wird.</p>"}, {"id": "FIG-e1cc3d0871a91436", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Verbindungsaufbaus, der Datenübertragung und des Verbindungsabbaus im SAE J1939 Transport Layer (J1939Tp) der AUTOSAR Classic Platform unter Nutzung der verbindungsgesteuerten Übertragung (Connection Mode Data Transfer, CMDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationspartner mit explizit benannten Rollen als vertikale, gestrichelte Lebenslinien: <code>Sender</code> (linke Lebenslinie) und <code>Receiver</code> (rechte Lebenslinie). Die Schnittstelle umfasst die SAE-J1939-TP-Nachrichten <code>TP.CM_RTS</code>, <code>TP.CM_CTS</code>, <code>TP.DT</code> und <code>TP.CM_EndOfMsgACK</code>. Neben den Timeouts T2 (Receiver-Wartezeit auf DT) und T3 (Sender-Wartezeit auf CTS) sind die Reaktionszeitgrenzen Tr (Response Time für Sender und Receiver) sowie T1 (Receiver-Timeout nach Erhalt des letzten Pakets eines Blocks) explizit ausgewiesen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Verbindungsaufbau: Der <code>Sender</code> sendet <code>TP.CM_RTS.3 Packets, 16 Bytes</code> an den <code>Receiver</code> und startet den Timer T3.\n</li><li>Flusssteuerung: Innerhalb der Reaktionszeit Tr antwortet der <code>Receiver</code> mit <code>TP.CM_CTS with 2 Packets</code>. Der Receiver überwacht den Eingang der Datenpakete mittels T2.\n</li><li>Erste Datenphase: Der <code>Sender</code> antwortet nach Tr mit dem ersten <code>TP.DT</code>-Paket und nach einem weiteren Tr mit dem zweiten <code>TP.DT</code>-Paket an den <code>Receiver</code>.\n</li><li>Zweite Flusssteuerungsphase: Nach Ablauf von T1 bzw. Verarbeitung des Blocks sendet der <code>Receiver</code> <code>TP.CM_CTS with 1 Packet</code>.\n</li><li>Zweite Datenphase: Der <code>Sender</code> überträgt das verbleibende dritte Paket <code>TP.DT</code>.\n</li><li>Abschluss: Der <code>Receiver</code> bestätigt den fehlerfreien Gesamtempfang mit <code>TP.CM_EndOfMsgACK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Zusammenspiel von Protokoll-Timeouts (T1, T2, T3) und System-Reaktionszeiten (Tr) bei der fehlerfreien CMDT-Übertragung im AUTOSAR J1939Tp. Implementierer müssen die Einhaltung der maximalen Antwortzeit Tr für CTS- und DT-Aussendungen gewährleisten und Timeouts bei Ausbleiben von Paketen über T1/T2/T3 deterministisch abfangen.</p>"}, {"id": "FIG-10c456e09c58a95f", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Verbindungsaufbaus, der Datenübertragung und des Verbindungsabbaus im SAE J1939 Transport Layer (J1939Tp) der AUTOSAR Classic Platform unter Nutzung der verbindungsgesteuerten Übertragung (Connection Mode Data Transfer, CMDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationspartner, die als vertikale, gestrichelte Lebenslinien dargestellt sind: den sendenden Knoten (Sender, links) und den empfangenden Knoten (Receiver, rechts). Kommuniziert wird über standardisierte J1939-Transportprotokollnachrichten: Connection Management Nachrichten (TP.CM_RTS, TP.CM_CTS, TP.CM_EndOfMsgACK) sowie Datenübertragungsnachrichten (TP.DT). Relevante Zeitparameter sind T2 (Receiver-Wartezeit auf das nächste Datenpaket) und T3 (Sender-Wartezeit auf CTS).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Verbindungsaufbau: Der Sender initiiert die CMDT-Sitzung durch Senden von <code>TP.CM_RTS</code> mit den Parametern für 3 Pakete und eine Gesamtnutzdatenlänge von 16 Bytes an den Receiver. Der Sender startet dabei die Überwachung des T3-Timeouts.\n</li><li>Bestätigung / Flusssteuerung: Der Receiver antwortet mit <code>TP.CM_CTS with 2 Packets</code>, wodurch der Sender autorisiert wird, zunächst zwei Pakete zu übertragen. Der Receiver startet die T2-Timeout-Überwachung für die ausstehenden Datenpakete.\n</li><li>Paketübertragung (Block 1): Der Sender überträgt aufeinanderfolgend zwei Datenpakete (<code>TP.DT</code>).\n</li><li>Erneute Flusssteuerung: Nach Empfang des zweiten Datenpakets sendet der Receiver ein weiteres <code>TP.CM_CTS with 1 Packet</code>.\n</li><li>Paketübertragung (Block 2): Der Sender sendet das dritte und letzte Datenpaket (<code>TP.DT</code>).\n</li><li>Verbindungsabschluss: Nach erfolgreichem Empfang aller spezifizierten Pakete schließt der Receiver die Transaktion mit einer Endbestätigung (<code>TP.CM_EndOfMsgACK</code>) ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für einen fehlerfreien CMDT-Übertragungsablauf gemäß SAE J1939-21 bzw. AUTOSAR J1939Tp. Entwickler müssen sicherstellen, dass die softwareseitige Flusssteuerung die Anzahl der in CTS angeforderten Pakete strikt einhält, Timeouts für T2 und T3 konform überwacht werden und der Puffer nach Erhalt des EndOfMsgACK freigegeben wird.</p>"}, {"id": "FIG-7093685b3007e7be", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Verbindungsaufbaus, der Datenübertragung und des Verbindungsabbaus im SAE J1939 Transport Layer (J1939Tp) der AUTOSAR Classic Platform unter Nutzung der verbindungsgesteuerten Übertragung (Connection Mode Data Transfer, CMDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationspartner, die als vertikale, gestrichelte Lebenslinien dargestellt sind: den sendenden Knoten (Sender, links) und den empfangenden Knoten (Receiver, rechts). Kommuniziert wird über standardisierte J1939-Transportprotokollnachrichten: Connection Management Nachrichten (TP.CM_RTS, TP.CM_CTS, TP.CM_EndOfMsgACK) sowie Datenübertragungsnachrichten (TP.DT). Relevante Zeitparameter sind T2 (Receiver-Wartezeit auf das nächste Datenpaket) und T3 (Sender-Wartezeit auf CTS).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Verbindungsaufbau: Der Sender initiiert die CMDT-Sitzung durch Senden von <code>TP.CM_RTS</code> mit den Parametern für 3 Pakete und eine Gesamtnutzdatenlänge von 16 Bytes an den Receiver. Der Sender startet dabei die Überwachung des T3-Timeouts.\n</li><li>Bestätigung / Flusssteuerung: Der Receiver antwortet mit <code>TP.CM_CTS with 2 Packets</code>, wodurch der Sender autorisiert wird, zunächst zwei Pakete zu übertragen. Der Receiver startet die T2-Timeout-Überwachung für die ausstehenden Datenpakete.\n</li><li>Paketübertragung (Block 1): Der Sender überträgt aufeinanderfolgend zwei Datenpakete (<code>TP.DT</code>).\n</li><li>Erneute Flusssteuerung: Nach Empfang des zweiten Datenpakets sendet der Receiver ein weiteres <code>TP.CM_CTS with 1 Packet</code>.\n</li><li>Paketübertragung (Block 2): Der Sender sendet das dritte und letzte Datenpaket (<code>TP.DT</code>).\n</li><li>Verbindungsabschluss: Nach erfolgreichem Empfang aller spezifizierten Pakete schließt der Receiver die Transaktion mit einer Endbestätigung (<code>TP.CM_EndOfMsgACK</code>) ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für einen fehlerfreien CMDT-Übertragungsablauf gemäß SAE J1939-21 bzw. AUTOSAR J1939Tp. Entwickler müssen sicherstellen, dass die softwareseitige Flusssteuerung die Anzahl der in CTS angeforderten Pakete strikt einhält, Timeouts für T2 und T3 konform überwacht werden und der Puffer nach Erhalt des EndOfMsgACK freigegeben wird.</p>"}, {"id": "FIG-aa51326cd36b0100", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Verbindungsaufbaus, der Datenübertragung und des Verbindungsabbaus im SAE J1939 Transport Layer (J1939Tp) der AUTOSAR Classic Platform unter Nutzung der verbindungsgesteuerten Übertragung (Connection Mode Data Transfer, CMDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Kommunikationspartner, die als vertikale, gestrichelte Lebenslinien dargestellt sind: den sendenden Knoten (Sender, links) und den empfangenden Knoten (Receiver, rechts). Kommuniziert wird über standardisierte J1939-Transportprotokollnachrichten: Connection Management Nachrichten (TP.CM_RTS, TP.CM_CTS, TP.CM_EndOfMsgACK) sowie Datenübertragungsnachrichten (TP.DT). Relevante Zeitparameter sind T2 (Receiver-Wartezeit auf das nächste Datenpaket) und T3 (Sender-Wartezeit auf CTS).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Verbindungsaufbau: Der Sender initiiert die CMDT-Sitzung durch Senden von <code>TP.CM_RTS</code> mit den Parametern für 3 Pakete und eine Gesamtnutzdatenlänge von 16 Bytes an den Receiver. Der Sender startet dabei die Überwachung des T3-Timeouts.\n</li><li>Bestätigung / Flusssteuerung: Der Receiver antwortet mit <code>TP.CM_CTS with 2 Packets</code>, wodurch der Sender autorisiert wird, zunächst zwei Pakete zu übertragen. Der Receiver startet die T2-Timeout-Überwachung für die ausstehenden Datenpakete.\n</li><li>Paketübertragung (Block 1): Der Sender überträgt aufeinanderfolgend zwei Datenpakete (<code>TP.DT</code>).\n</li><li>Erneute Flusssteuerung: Nach Empfang des zweiten Datenpakets sendet der Receiver ein weiteres <code>TP.CM_CTS with 1 Packet</code>.\n</li><li>Paketübertragung (Block 2): Der Sender sendet das dritte und letzte Datenpaket (<code>TP.DT</code>).\n</li><li>Verbindungsabschluss: Nach erfolgreichem Empfang aller spezifizierten Pakete schließt der Receiver die Transaktion mit einer Endbestätigung (<code>TP.CM_EndOfMsgACK</code>) ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für einen fehlerfreien CMDT-Übertragungsablauf gemäß SAE J1939-21 bzw. AUTOSAR J1939Tp. Entwickler müssen sicherstellen, dass die softwareseitige Flusssteuerung die Anzahl der in CTS angeforderten Pakete strikt einhält, Timeouts für T2 und T3 konform überwacht werden und der Puffer nach Erhalt des EndOfMsgACK freigegeben wird.</p>"}], "trans": [{"from": "FIG-580bc757974fff31", "to": "FIG-e1cc3d0871a91436", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Rollenbezeichner: Oberhalb der Lebenslinien wurden die Bezeichner „Sender“ (linke Lebenslinie) und „Receiver“ (rechte Lebenslinie) explizit ergänzt.\n</li><li>Timer-Beschriftungen: An den horizontalen Reaktionszeit-Pfeilen wurden die Bezeichner „Tr“ (zweimal links beim Sender, einmal rechts beim Receiver) sowie „T1“ (rechts beim Receiver nach dem zweiten TP.DT-Paket) ergänzt; zuvor waren an diesen Stellen nur Pfeile ohne Textbeschriftung vorhanden bzw. abgeschnitten.\n</li></ul>"}, {"from": "FIG-e1cc3d0871a91436", "to": "FIG-10c456e09c58a95f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Rollenbezeichner: Die Bezeichner „Sender“ und „Receiver“ am Kopf der Lebenslinien wurden entfernt.\n</li><li>Timer-Beschriftungen: Die Beschriftungen „Tr“ (dreifach) und „T1“ wurden entfernt bzw. durch das engere Zuschneiden der Bildränder abgeschnitten, sodass dort wieder nur unbeschriftete Pfeile verbleiben.\n</li></ul>"}, {"from": "FIG-10c456e09c58a95f", "to": "FIG-7093685b3007e7be", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7093685b3007e7be", "to": "FIG-aa51326cd36b0100", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
